import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../AuthContext';
import { publicApi } from '../services/api';
import './Login.css';
import Lottie from 'lottie-react';
import splashAnimation from '../Login.json';

function Login() {
  useEffect(() => {
    document.body.classList.add('login-body');
    return () => document.body.classList.remove('login-body');
  }, []);

  const { login } = useAuth();
  const navigate = useNavigate();
  const [role, setRole] = useState('admin');
  const [departments, setDepartments] = useState([]);
  const [form, setForm] = useState({
    email: '',
    password: '',
    facultyId: '',
    facultyName: '',
    studentEmail: '',
    departmentId: '',
    sectionNumber: 1
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (role === 'student') {
      publicApi.getDepartments().then(setDepartments).catch(() => setDepartments([]));
    }
  }, [role]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
      let payload;
      if (role === 'admin') {
        payload = {
          role: 'admin',
          email: form.email,
          password: form.password
        };
      } else if (role === 'faculty') {
        payload = {
          role: 'faculty',
          facultyId: form.facultyId,
          name: form.facultyName
        };
      } else {
        payload = {
          role: 'student',
          email: form.studentEmail,
          departmentId: form.departmentId,
          sectionNumber: Number(form.sectionNumber) || 1
        };
      }
      const user = await login(payload);
      if (user.role === 'admin') {
        navigate('/');
      } else if (user.role === 'faculty') {
        navigate('/faculty-schedule');
      } else if (user.role === 'student') {
        navigate('/student-timetable');
      } else {
        navigate('/');
      }
    } catch (err) {
      setError(err.message || 'Login failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-page">
      <div className="login-image-block">
        <div className="login-lottie-wrap">
          <Lottie
            animationData={splashAnimation}
            loop
            className="login-lottie"
            style={{ width: '100%', height: 280, maxWidth: 320 }}
          />
        </div>
      </div>

      <div className="login-form-block">
        <div className="login-card">
          <h1>Sign in</h1>
          <p className="login-subtitle">Choose your role and enter your details.</p>

          {error && <div className="alert alert-error">{error}</div>}

          <form onSubmit={handleSubmit} className="login-form">
            <div className="form-group">
              <label>Login as</label>
              <select
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="login-role-select"
              >
                <option value="admin">Admin</option>
                <option value="faculty">Faculty</option>
                <option value="student">Student</option>
              </select>
            </div>

            {role === 'admin' && (
              <>
                <div className="form-group">
                  <label>Email</label>
                  <input
                    type="email"
                    required
                    value={form.email}
                    onChange={(e) => setForm((prev) => ({ ...prev, email: e.target.value }))}
                    placeholder="admin@example.com"
                  />
                </div>
                <div className="form-group">
                  <label>Password</label>
                  <input
                    type="password"
                    required
                    value={form.password}
                    onChange={(e) => setForm((prev) => ({ ...prev, password: e.target.value }))}
                    placeholder="••••••••"
                  />
                </div>
              </>
            )}

            {role === 'faculty' && (
              <>
                <div className="form-group">
                  <label>Faculty ID</label>
                  <input
                    required
                    value={form.facultyId}
                    onChange={(e) => setForm((prev) => ({ ...prev, facultyId: e.target.value }))}
                    placeholder="e.g. CSE001"
                  />
                </div>
                <div className="form-group">
                  <label>Name</label>
                  <input
                    required
                    value={form.facultyName}
                    onChange={(e) => setForm((prev) => ({ ...prev, facultyName: e.target.value }))}
                    placeholder="Exact name as in Faculty list"
                  />
                </div>
              </>
            )}

            {role === 'student' && (
              <>
                <div className="form-group">
                  <label>Email</label>
                  <input
                    type="email"
                    required
                    value={form.studentEmail}
                    onChange={(e) => setForm((prev) => ({ ...prev, studentEmail: e.target.value }))}
                    placeholder="student@example.com"
                  />
                </div>
                <div className="form-group form-row">
                  <div className="form-group-inline">
                    <label>Department</label>
                    <select
                      required
                      value={form.departmentId}
                      onChange={(e) => setForm((prev) => ({ ...prev, departmentId: e.target.value }))}
                      className="login-dept-select"
                    >
                      <option value="">Select department</option>
                      {departments.map((d) => (
                        <option key={d._id} value={d._id}>
                          {d.departmentId || d.name}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="form-group-inline">
                    <label>Section</label>
                    <input
                      type="number"
                      min={1}
                      max={20}
                      required
                      value={form.sectionNumber}
                      onChange={(e) => setForm((prev) => ({ ...prev, sectionNumber: e.target.value }))}
                      placeholder="1"
                    />
                  </div>
                </div>
              </>
            )}

            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Signing in...' : 'Sign in'}
            </button>

            <div className="divider">
              <span>OR</span>
            </div>
            <button
              type="button"
              className="google-btn"
              onClick={() => console.log('Sign in with Google')}
            >
              <img
                src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
                alt="Google"
                className="google-icon"
              />
              Sign in with Google
            </button>
          </form>
        </div>
      </div>
    </div>
  );
}

export default Login;
